// Scheduled matches for a gender, soonest first (today before tomorrow).
export function getUpcoming(gender) {
  return gender ? upcoming.filter((r) => r.gender === gender) : upcoming;
}
export function getUpcomingDoubles(gender) {
  return gender ? upcomingDoubles.filter((r) => r.gender === gender) : upcomingDoubles;
}

